#include "dhcp_core.h"
static uint32_t get32(const uint8_t*p){return((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
int dhcp_parse(const uint8_t*p,uint32_t n,struct dhcp_view*out){if(!p||!out||n<240||p[2]==0||p[2]>16)return -1;if(get32(p+236)!=0x63825363U)return -1;out->op=p[0];out->hardware_type=p[1];out->hardware_length=p[2];out->xid=get32(p+4);out->client_ip=get32(p+12);out->your_ip=get32(p+16);out->server_ip=get32(p+20);out->client_hardware=p+28;out->message_type=0;out->server_identifier=out->subnet_mask=out->lease_seconds=out->renewal_seconds=out->rebind_seconds=0;uint8_t ended=0;for(uint32_t i=240;i<n;){uint8_t code=p[i++];if(code==0)continue;if(code==255){ended=1;break;}if(i>=n)return -1;uint8_t len=p[i++];if((uint32_t)len>n-i)return -1;uint32_t value=(len==4)?get32(p+i):0;if(code==53){if(len!=1||out->message_type)return -1;out->message_type=p[i];}else if(code==54){if(len!=4||out->server_identifier)return -1;out->server_identifier=value;}else if(code==1){if(len!=4||out->subnet_mask)return -1;out->subnet_mask=value;}else if(code==51){if(len!=4||out->lease_seconds)return -1;out->lease_seconds=value;}else if(code==58){if(len!=4||out->renewal_seconds)return -1;out->renewal_seconds=value;}else if(code==59){if(len!=4||out->rebind_seconds)return -1;out->rebind_seconds=value;}i+=len;}if(!ended||!out->message_type)return -1;return 0;}
int dhcp_client_start(struct dhcp_client*c,uint32_t xid,uint32_t now){if(!c||!xid)return -1;c->state=DHCP_SELECTING;c->xid=xid;c->address=c->server=0;c->lease_start=c->lease_seconds=c->renewal_seconds=c->rebind_seconds=0;c->deadline=now;c->retries=0;return 0;}
int dhcp_client_receive(struct dhcp_client*c,const uint8_t*p,uint32_t n,uint32_t now){if(!c)return -1;struct dhcp_view v;if(dhcp_parse(p,n,&v)!=0||v.xid!=c->xid||v.op!=2)return -1;if(c->state==DHCP_SELECTING&&v.message_type==2&&v.your_ip&&v.server_identifier){c->address=v.your_ip;c->server=v.server_identifier;c->state=DHCP_REQUESTING;c->deadline=now;c->retries=0;return 1;}if((c->state==DHCP_REQUESTING||c->state==DHCP_RENEWING||c->state==DHCP_REBINDING)&&v.message_type==6){c->state=DHCP_SELECTING;c->address=c->server=0;c->deadline=now;c->retries=0;return 2;}if((c->state==DHCP_REQUESTING||c->state==DHCP_RENEWING||c->state==DHCP_REBINDING)&&v.message_type==5&&v.your_ip&&v.lease_seconds){uint32_t lease=v.lease_seconds;if(lease>=0x80000000U)return -1;uint32_t t1=v.renewal_seconds?v.renewal_seconds:lease/2U;uint32_t t2=v.rebind_seconds?v.rebind_seconds:(lease-(lease/8U));if(t1>=t2||t2>=lease)return -1;c->address=v.your_ip;c->server=v.server_identifier?v.server_identifier:c->server;c->lease_start=now;c->lease_seconds=lease;c->renewal_seconds=t1;c->rebind_seconds=t2;c->deadline=now+t1;c->retries=0;c->state=DHCP_BOUND;return 3;}return -1;}
enum dhcp_action dhcp_client_tick(struct dhcp_client*c,uint32_t now,uint32_t interval,uint32_t limit){if(!c||!interval||interval>=0x80000000U)return DHCP_ACTION_NONE;if(c->state==DHCP_BOUND||c->state==DHCP_RENEWING||c->state==DHCP_REBINDING){if((int32_t)(now-(c->lease_start+c->lease_seconds))>=0){c->state=DHCP_FAILED;c->address=0;return DHCP_ACTION_EXPIRED;}if(c->state==DHCP_BOUND&&(int32_t)(now-(c->lease_start+c->renewal_seconds))>=0){c->state=DHCP_RENEWING;c->deadline=now;c->retries=0;return DHCP_ACTION_RENEW;}if(c->state==DHCP_RENEWING&&(int32_t)(now-(c->lease_start+c->rebind_seconds))>=0){c->state=DHCP_REBINDING;c->deadline=now;c->retries=0;return DHCP_ACTION_REBIND;}}if((c->state==DHCP_SELECTING||c->state==DHCP_REQUESTING||c->state==DHCP_RENEWING||c->state==DHCP_REBINDING)&&(int32_t)(now-c->deadline)>=0){if(c->retries>=limit){if(c->state==DHCP_SELECTING||c->state==DHCP_REQUESTING)c->state=DHCP_FAILED;return DHCP_ACTION_NONE;}c->retries++;c->deadline=now+interval;if(c->state==DHCP_SELECTING)return DHCP_ACTION_DISCOVER;if(c->state==DHCP_REQUESTING)return DHCP_ACTION_REQUEST;if(c->state==DHCP_RENEWING)return DHCP_ACTION_RENEW;return DHCP_ACTION_REBIND;}return DHCP_ACTION_NONE;}
